#include "gateway_public_page.h"

const char GATEWAY_PUBLIC_PAGE[] =
"<!doctype html><html lang='vi'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><meta name='color-scheme' content='dark'><title>AUBOT | Tổng quan kho</title><link rel='stylesheet' href='/ui.css?v=5'><style>"
".warehouse-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}.warehouse-tile{min-height:130px;padding:15px;border:1px solid var(--line);border-radius:11px;background:var(--glass)}.warehouse-tile .position{display:block;color:#dbeafe;font-size:17px;font-weight:850}.warehouse-tile .state{display:block;margin-top:18px;font-size:15px;font-weight:850}.warehouse-tile.EMPTY{border-color:rgba(52,211,153,.4);background:rgba(20,53,48,.7)}.warehouse-tile.EMPTY .state{color:#a7f3d0}.warehouse-tile.OCCUPIED{border-color:rgba(251,191,36,.48);background:rgba(64,47,20,.7)}.warehouse-tile.OCCUPIED .state{color:#fde68a}.summary{display:grid;grid-template-columns:repeat(4,1fr);gap:8px}.summary div{padding:9px 11px;border:1px solid var(--line2);border-radius:9px;background:var(--glass2)}.summary small{display:block;color:var(--muted);font-size:10px}.summary b{display:block;margin-top:3px}@media(max-width:760px){.warehouse-grid{grid-template-columns:repeat(2,1fr)}.summary{grid-template-columns:repeat(2,1fr)}}@media(max-width:390px){.warehouse-grid{grid-template-columns:1fr}}</style></head><body data-page='overview'><div class='shell'>"
"<header class='hero'><div class='brand'><img class='logo' src='/logo.png' alt='AUBOT'><div><div class='eyebrow'>AUBOT · WAREHOUSE GATEWAY</div><h1>Tổng quan kho</h1><p>Có hàng · Không có hàng · Chưa xác định</p></div></div><div data-app-user></div></header><div data-system-bar></div><nav class='nav' data-app-nav></nav><section class='toolbar summary'><div><small>Vị trí</small><b id='count'>0</b></div><div><small>Không có hàng</small><b id='empty'>0</b></div><div><small>Có hàng</small><b id='occupied'>0</b></div><div><small>Chưa xác định</small><b id='unknown'>0</b></div></section><main id='grid' class='warehouse-grid'></main></div><script src='/ui.js?v=5'></script><script>const $=x=>document.getElementById(x),label=s=>s==='EMPTY'?'KHÔNG CÓ HÀNG':s==='OCCUPIED'?'CÓ HÀNG':'CHƯA XÁC ĐỊNH';const tiles=Array(13);function ensure(n){for(let i=1;i<=n;i++)if(!tiles[i]){const a=document.createElement('article');a.innerHTML=`<strong class='position'>VỊ TRÍ ${i}</strong><span class='state'>CHƯA XÁC ĐỊNH</span>`;$('grid').append(a);tiles[i]=a}for(let i=n+1;i<tiles.length;i++)if(tiles[i])tiles[i].remove(),tiles[i]=null}function render(d){$('count').textContent=d.position_count;$('empty').textContent=d.empty;$('occupied').textContent=d.occupied;$('unknown').textContent=d.unknown;ensure(d.position_count);for(const p of d.positions){const a=tiles[p.position_id],cls='warehouse-tile '+p.state;if(a.className!==cls)a.className=cls;const state=a.querySelector('.state'),st=label(p.state);if(state.textContent!==st)state.textContent=st}}async function poll(){if(document.hidden){setTimeout(poll,10000);return}try{render(await gw.fetchJson('/api/public/status'))}catch(e){}setTimeout(poll,1800)}document.addEventListener('visibilitychange',()=>{if(!document.hidden)poll()});poll()</script></body></html>";
